insert into topics (chapter_id,slug,title,summary,analogy,position) values (1,'t1','Testing vs debugging','Testing finds failures; debugging locates and removes their causes. Confirmation testing checks the fix.',null,0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (1,'t2','Seven principles','Presence not absence of defects, no exhaustive testing, early testing, defect clustering, tests wear out, context, absence-of-defects fallacy.',null,1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (1,'t3','Test process','Planning, monitoring and control, analysis, design, implementation, execution, completion.',null,2);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (2,'t4','Test levels','Component, component integration, system, system integration and acceptance testing.',null,0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (2,'t5','Test types','Functional, non-functional, black-box and white-box testing.',null,1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (2,'t6','Change-related','Confirmation testing checks a fix; regression testing checks for side effects.','Fix the tap, then test every other tap for new leaks: the first is confirmation, the second is regression.',2);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (3,'t7','Static vs dynamic','Static testing examines work products without running code and finds defects early.',null,0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (3,'t8','Review process','Planning, initiation, individual review, communication and analysis, fixing and reporting.',null,1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (3,'t9','Review types','Informal, walkthrough, technical review, inspection (most formal).',null,2);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (4,'t10','Black-box','Equivalence partitioning, boundary value analysis, decision tables, state transitions.','Testing a vending machine only through its buttons and coin slot, without opening the case.',0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (4,'t11','White-box','Statement and branch coverage. 100% branch coverage implies 100% statement coverage.','A mechanic inspecting the engine itself instead of just driving the car.',1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (4,'t12','Experience-based','Error guessing, exploratory testing and checklist-based testing.',null,2);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (5,'t13','Planning & estimation','Entry and exit criteria; ratio, extrapolation, Wideband Delphi, three-point (a+4m+b)/6.','Estimating a commute with best, likely and worst cases instead of one hopeful number.',0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (5,'t14','Risk-based testing','Risk level = likelihood x impact. Product and project risks drive priority.','Packing by what hurts most to forget (passport) before what is merely nice (a book).',1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (5,'t15','Defect management','Reports record expected vs actual results, severity, priority, status and environment.',null,2);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (6,'t16','Tool categories','Management, static, design, execution and coverage, performance, DevOps tools.',null,0);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (6,'t17','Automation benefits','Saves repetitive effort, adds consistency and objectivity, reduces human error.',null,1);
insert into topics (chapter_id,slug,title,summary,analogy,position) values (6,'t18','Automation risks','Unrealistic expectations, underestimated effort, testware maintenance, over-reliance.',null,2);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K1','Which of the following is one of the seven testing principles?',array['Testing can prove the absence of defects','Testing shows the presence, not the absence, of defects','Early testing is rarely cost effective','Defects are evenly distributed'],1,'Think about what testing can never guarantee.','Principle 1: testing reduces the probability of undiscovered defects but cannot prove correctness. Defects cluster, and early testing saves cost.',null,1,null,30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K1','Which of the following is a test level?',array['Component testing','Boundary value testing','Smoke testing','Exploratory testing'],0,'Levels are about scope in the lifecycle, not technique.','Levels: component, component integration, system, system integration, acceptance. The others are techniques or approaches.',null,1,null,30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K2','What distinguishes confirmation testing from regression testing?',array['Confirmation is automated, regression is manual','Confirmation checks a fix worked; regression checks for unintended side effects','Regression happens only at acceptance level','Confirmation is a non-functional test type'],1,'One looks at the fixed defect, the other at everything around it.','After a fix, confirmation re-runs the failed test. Regression tests surrounding functionality for adverse effects.','After fixing a leaking tap you check that the tap now runs dry (confirmation). Then you run every other tap and look at the ceiling below for new damp patches (regression).',2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K2','Which statement about coverage is correct?',array['100% statement coverage guarantees 100% branch coverage','100% branch coverage guarantees 100% statement coverage','They are always equal','Neither can be measured on code'],1,'Branches include every outcome of every decision.','Exercising every branch outcome executes every reachable statement. The reverse fails, e.g. an if without an else.','Statement coverage is visiting every room in a house. Branch coverage also means walking through every door both ways. You can visit every room without ever trying some doors.',2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K3','An age field accepts 18 to 65 inclusive. Using 2-value boundary value analysis, which values do you test?',array['17, 18, 65, 66','18, 19, 64, 65','17, 18, 19, 65, 66','0, 18, 65, 100'],0,'2-value BVA: each boundary plus its closest neighbor in the adjacent partition.','Boundaries are 18 and 65; the closest invalid neighbors are 17 and 66. 3-value BVA would also add 19 and 64.','A cinema checks age at the 18 line. Staff slip up right at the cutoff, so you test the person just under it and the person exactly on it, not someone aged 40.',3,null,120);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K3','Estimates: optimistic 6, most likely 12, pessimistic 24 days. What is the three-point estimate (a+4m+b)/6?',array['12','13','14','15'],1,'Weight the most likely value four times.','(6 + 4 x 12 + 24) / 6 = 78 / 6 = 13 days.','Commute estimate: best 20 min, typical 30, worst 60 in traffic. (20 + 4x30 + 60) / 6 = 33 min, a more honest answer than a flat 30.',3,null,120);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K3','A shop discount applies to valid order totals as follows: 1.00 to 99.99 gets no discount, 100.00 to 499.99 gets 5%, and 500.00 or more gets 10%. Using equivalence partitioning, what is the minimum number of test cases to cover all valid partitions?',array['2','3','4','6'],1,'One representative value per partition is enough.','There are three valid equivalence partitions, so at least one test case per partition is needed: 3. Invalid partitions (such as zero or negative totals) would need additional tests.','A canteen charges by age band: child, student, adult. If the till is right for one child ticket, it is assumed right for every child, so you test one ticket per band, not every possible age.',2,null,120);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K3','A discount rule depends on three independent true/false conditions: member, coupon, first order. How many rules (columns) does the full decision table have before any collapsing?',array['3','6','8','9'],2,'Each extra condition doubles the number of combinations.','With 3 binary conditions there are 2 x 2 x 2 = 8 combinations. Collapsing merges rules where a condition does not affect the outcome.','Three yes/no questions before a trip (rain? beach? flight?) give 8 possible packing lists. The table writes them all down so no combination is forgotten.',2,null,120);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K2','Which statement about state transition testing is correct?',array['Test cases are derived from states, events, transitions and actions','It can only be applied to source code','It ignores the history of earlier events','It is a white-box technique based on branches'],0,'Think of a system that behaves differently depending on what happened before.','State transition testing is a black-box technique: the same event can produce different results depending on the current state, and tests exercise states and transitions.','In a lift, pressing Up does different things when the doors are open, closing, or the car is moving. Same input, different outcome, because the state is different.',2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K3','A field accepts integers from 1 to 100 inclusive. Using 3-value boundary value analysis, how many test values are needed?',array['2','4','6','8'],2,'Each boundary gets itself plus a neighbor on each side.','Boundary 1 gives 0, 1, 2 and boundary 100 gives 99, 100, 101. That is 6 distinct values.','A speed camera triggers at 100 km/h. Bugs hide at the edge (less-than vs less-or-equal), so you check 99, 100 and 101 rather than a random 60.',3,null,120);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K2','Which of the following is a project risk rather than a product risk?',array['The reporting module calculates totals incorrectly','A key test analyst leaves the project part-way through','The system responds too slowly under peak load','The user interface confuses new users'],1,'Project risks concern how the project is managed and resourced, not the quality of the product.','Staff loss affects project delivery. Incorrect calculations, poor performance and confusing UI are product risks about the quality of the test object.','Building a house: a cracked foundation is a product risk (the thing itself is flawed). The builder quitting halfway is a project risk (the way it is being delivered).',2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K1','Which review type is the most formal?',array['Informal review','Walkthrough','Technical review','Inspection'],3,'It follows a defined process with roles and exit criteria.','CTFL v4.0 lists informal review, walkthrough, technical review and inspection; inspection is the most formal.',null,1,null,30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K2','Which is an advantage of static testing over dynamic testing?',array['It needs an executable build','It can find defects in work products, such as requirements, before any code exists','It identifies performance bottlenecks','It makes dynamic testing unnecessary'],1,'Static testing does not run the software.','Static testing examines work products without executing them, so defects such as ambiguous requirements are found early and cheaply. It complements, not replaces, dynamic testing.',null,2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=6 order by position limit 1),'K1','Which is a potential benefit of test automation?',array['It removes the need for test design','Greater consistency and fewer human errors in repetitive tasks','It guarantees defect-free software','It needs no maintenance'],1,'Machines are good at repeating the same thing exactly.','Benefits include time savings on repetitive work, greater consistency and more objective assessment. Automation still needs design and maintenance.',null,1,null,30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=6 order by position limit 1),'K2','Which is a typical risk of introducing test automation?',array['Unrealistic expectations about what it will deliver','It always reduces coverage','Tools cannot execute tests','Defect reports become impossible'],0,'Think about expectations versus effort.','Typical risks include unrealistic expectations, underestimating the effort to build and maintain testware, and over-reliance on the tool.',null,2,null,60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K1','Which of the following best describes a failure?',array['A human mistake made while writing code','A flaw in a work product that may cause wrong behavior','An event in which a component or system does not perform a required function','The earliest condition that created a defect'],2,'A failure is what is observed when the software runs.','A human error can introduce a defect; executing the defect may cause a failure, which is the observable event of a required function not being performed.',null,1,'A',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K2','A payment screen shows a wrong total. The developer finds that a tax rate constant was mistyped in the code. Which pairing is correct?',array['Wrong total is the defect; mistyped constant is the failure','Wrong total is the failure; mistyped constant is the defect','Wrong total is the error; mistyped constant is the failure','Wrong total is the root cause; mistyped constant is the error'],1,'Which one do users see, and which one lives in the code?','The observable wrong behavior is the failure. The incorrect constant in the code is the defect, introduced by a human error (the typo).','A recipe typo (defect) makes the cake taste salty (failure). The cook''s slip while copying the recipe was the error.',3,'B',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K2','Which statement correctly contrasts testing with quality assurance?',array['Quality assurance is product-oriented and corrective; testing is process-oriented and preventive','Testing is product-oriented and corrective (quality control); quality assurance is process-oriented and preventive','Both are purely preventive','Both are purely corrective'],1,'One looks at the product, the other at the process.','Testing is a quality control activity: product-oriented and corrective. Quality assurance focuses on processes and prevention.',null,2,'C',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K1','Which testing principle says that repeating the same tests over and over finds fewer and fewer new defects?',array['Defects cluster together','Tests wear out','Exhaustive testing is impossible','Early testing saves time and money'],1,'Think about tests losing their power over time.','Principle 5, tests wear out: if the same tests are repeated, they stop finding new defects, so they must be reviewed and updated.',null,1,'D',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=1 order by position limit 1),'K2','The principle ''defects cluster together'' suggests what for test effort?',array['Spread effort evenly over all modules','Focus more testing on the small number of modules likely to contain most defects','Stop testing a module once one defect is found','Test only the module changed last'],1,'A few modules usually hold most of the defects.','Defects tend to concentrate in a small number of modules, so risk-based focus on those areas is more effective than even coverage.',null,2,'A',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K1','Which test level focuses on interfaces and interactions between components?',array['Component testing','Component integration testing','Acceptance testing','Regression testing'],1,'The name says what is integrated.','Component integration testing focuses on the interfaces and interactions between components. Regression testing is a change-related test type, not a level.',null,1,'B',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K2','Which statement about non-functional testing is correct?',array['It evaluates characteristics such as performance efficiency, usability and security','It can only be performed at acceptance level','It does not need test cases','It checks only what the system does, never how well'],0,'Functional is about what, non-functional is about how well.','Non-functional testing evaluates quality characteristics (for example performance efficiency, usability, reliability, security) and can be done at any test level.',null,2,'C',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K1','Which of the following is a trigger for maintenance testing?',array['Migration of the system to a new platform','Completion of component testing','Approval of the test plan','Start of exploratory testing'],0,'Maintenance happens after a system is in operation.','Triggers for maintenance testing are modification, migration and retirement of the system.',null,1,'D',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=2 order by position limit 1),'K2','In acceptance test-driven development (ATDD), when are acceptance tests created?',array['Before implementation, derived from the acceptance criteria','After the release','Only by developers after coding','Only during operational acceptance testing'],0,'ATDD is a test-first approach.','ATDD derives acceptance tests from acceptance criteria during story refinement, before the story is implemented.',null,2,'A',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K1','Which review role records anomalies, decisions and findings raised during the review meeting?',array['Author','Moderator','Scribe','Manager'],2,'Also called the recorder.','The scribe (recorder) collates anomalies from reviewers and records decisions and new anomalies found during the review meeting.',null,1,'B',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K1','In which review activity do reviewers review the work product on their own and note anomalies?',array['Planning','Review initiation','Individual review','Fixing and reporting'],2,'Each reviewer works alone at this point.','Review activities are planning, review initiation, individual review, communication and analysis, and fixing and reporting. Reviewers find anomalies independently during individual review.',null,1,'C',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K2','Which is a typical success factor for reviews?',array['Reviewing very large work products in a single session','Defining clear objectives and measurable exit criteria','Using the review to evaluate the author''s performance','Skipping planning for informal reviews'],1,'Think about what makes reviews effective and safe for participants.','Clear objectives and measurable exit criteria are success factors. Evaluating participants should never be an objective, and work products should be reviewed in small chunks.',null,2,'D',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=3 order by position limit 1),'K2','Which statement correctly distinguishes static analysis from dynamic testing?',array['Static analysis requires executing the code; dynamic testing does not','Static analysis can find defects such as unreachable code without executing the code','Dynamic testing can only find defects in requirements','Static analysis applies only to test cases'],1,'Which of the two runs the software?','Static analysis evaluates work products without executing them, so it can find defects such as unreachable code or undefined variables. Dynamic testing executes the test object and reveals failures.',null,3,'A',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K1','Which technique divides data into partitions that the test object is expected to process in the same way?',array['Equivalence partitioning','Statement testing','Error guessing','Checklist-based testing'],0,'The name contains the answer.','Equivalence partitioning divides data into partitions expected to be handled alike, so one value can represent each partition.',null,1,'B',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K2','Which statement about exploratory testing is correct?',array['Test design, execution and learning happen at the same time, often guided by a test charter','All test cases must be fully written before any execution','It cannot be time-boxed','It is a white-box technique'],0,'Think of learning while testing.','In exploratory testing, tests are designed, executed and evaluated while learning about the test object, often in time-boxed sessions guided by a charter.','A food critic wandering a market follows leads and takes notes as they learn, with a time limit and a goal, instead of ticking items off a fixed menu.',2,'C',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K2','In decision table testing, how is coverage measured?',array['Feasible columns exercised by at least one test, divided by total feasible columns','Conditions divided by actions','States visited divided by total states','Branches executed divided by total branches'],0,'A decision table is made of columns (rules).','Decision table coverage is the number of columns exercised by at least one test case divided by the total number of feasible columns.',null,3,'D',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K1','Which of the following is a white-box technique?',array['Branch testing','Boundary value analysis','Exploratory testing','Decision table testing'],0,'White-box uses the structure of the code.','Statement testing and branch testing are white-box techniques. The others are black-box or experience-based.',null,1,'A',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=4 order by position limit 1),'K2','In the three Cs of a user story, what does Confirmation refer to?',array['The acceptance criteria and tests that confirm the story is done','The written description on the card','The discussion between stakeholders','The sign-off by the project manager'],0,'The three Cs are Card, Conversation, Confirmation.','Card is the story description, Conversation is the discussion, and Confirmation is the acceptance criteria and tests that confirm the story is complete.',null,2,'B',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K1','Which of the following is an example of an exit criterion?',array['The test environment is available','Planned tests have been executed and all critical defects are resolved or accepted','Test data has been prepared','Testers have been trained'],1,'Exit criteria say when testing can stop.','Exit criteria include planned tests executed, coverage reached and defect thresholds met. Environment, data and resources are typical entry criteria.',null,2,'C',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K1','Which estimation technique is iterative, with experts estimating separately and then discussing deviations until consensus?',array['Ratio-based estimation','Extrapolation','Wideband Delphi','Three-point estimation'],2,'It is named after an oracle.','Wideband Delphi is an iterative, expert-based technique: experts estimate in isolation, discuss out-of-range deviations, and re-estimate until they reach consensus.',null,2,'D',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K2','In the test pyramid model, which is typically true of the lower layers compared with the top layer?',array['They have fewer tests that are slower and more expensive','They have more tests that are faster and more isolated','They always test the user interface','They can only be run manually'],1,'Low layers are small and fast.','The pyramid shows that lower layers contain more small, fast, isolated tests, while the top layer has fewer, slower, broader tests.','In a building you run lots of cheap, fast checks on every brick (unit level) and only a few slow, costly walkthroughs of the finished house (UI level).',2,'A',60);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=5 order by position limit 1),'K1','Which information is typically included in a defect report?',array['Expected and actual results, severity and the test environment','Only the defect title','The name of the developer who must fix it','The estimated cost of the fix'],0,'A good report lets someone reproduce the problem.','A defect report typically includes identifier, title, test object and environment, a description with steps to reproduce, expected and actual results, severity, priority and status.',null,1,'B',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=6 order by position limit 1),'K1','Which category of tools is used to run tests automatically and measure coverage?',array['Test management tools','Test execution and coverage tools','Static analysis tools','Collaboration tools'],1,'The category name says what it does.','Test execution and coverage tools run tests and measure coverage. Management tools organize testing, and static tools analyze work products without executing them.',null,1,'C',30);
insert into questions (topic_id,k_level,stem,options,correct_index,hint,explanation,analogy,difficulty,exam_set,expected_time_sec) values ((select id from topics where chapter_id=6 order by position limit 1),'K2','Why is over-reliance on a test automation tool a risk?',array['The tool can replace the judgment needed to design and evaluate tests','Tools always make testing slower','Tools cannot run regression tests','Tools remove all maintenance work'],0,'Tools support testers, they do not replace them.','Over-reliance on a tool can lead teams to skip the thinking needed for good test design and evaluation. Automation still needs design and maintenance.','Switching on autopilot does not remove the need for a pilot who knows what to check and when to take over.',3,'D',60);
insert into summary_sections (chapter_id,position,title,points,memo) values (1,0,'What testing is',array['Testing is a set of activities to discover defects and evaluate the quality of software work products (the test object).','Testing can be dynamic (the test object is executed) or static (reviews and static analysis; nothing is executed).','Typical objectives: evaluate work products, trigger failures and find defects, ensure required coverage, reduce the level of risk, verify that requirements are met, validate that the test object works as users expect, build confidence, provide information for decisions, and comply with contractual, legal or regulatory requirements.','Testing is not debugging. Testing can trigger failures caused by defects; debugging is a development activity that finds, analyzes and removes the cause. Confirmation testing then checks that the fix worked.'],array['Testing = find defects + evaluate quality','Dynamic runs the code, static does not','Testing finds, debugging fixes']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=0),'Error','A human mistake that can introduce a defect.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=0),'Defect','A flaw in a work product (also called a fault or bug) that may cause a failure.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=0),'Failure','An event in which a component or system does not perform a required function.',2);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=0),'Root cause','The earliest action or condition that created a defect, found by root cause analysis.',3);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=0),'Test object','The work product being tested.',4);
insert into summary_sections (chapter_id,position,title,points,memo) values (1,1,'Why testing is necessary',array['Testing helps meet requirements, reduces the risk of failures in operation, and finds defects early when they are cheaper to fix.','Testing is a form of quality control: product-oriented and corrective. Quality assurance is process-oriented and preventive.','Root cause analysis of defects and failures helps prevent similar defects and improves processes.','Cause chain: a human error introduces a defect; executing the defect may cause a failure.'],array['Quality control = product, corrective','Quality assurance = process, preventive','Error, then defect, then failure']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=1),'Quality assurance','Process-oriented, preventive approach that focuses on correct implementation of the process.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=1),'Quality control','Product-oriented, corrective approach; testing is a quality control activity.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (1,2,'Seven testing principles',array['1. Testing shows the presence, not the absence, of defects.','2. Exhaustive testing is impossible; use risk analysis and priorities to focus the effort.','3. Early testing saves time and money (shift left).','4. Defects cluster together: a small number of modules usually contain most defects.','5. Tests wear out: repeating the same tests finds fewer new defects, so tests must be updated.','6. Testing is context dependent: a safety-critical system is tested differently from an e-commerce site.','7. Absence-of-defects is a fallacy: a system with no known defects can still fail to meet user needs.'],array['Presence, not absence','Exhaustive is impossible','Early saves money','Defects cluster','Tests wear out','Context dependent','Absence-of-defects fallacy']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=2),'Exhaustive testing','Testing all combinations of inputs and preconditions; not feasible except in trivial cases.',0);
insert into summary_sections (chapter_id,position,title,points,memo) values (1,3,'Test process and roles',array['Test process activities: test planning, test monitoring and control, test analysis, test design, test implementation, test execution, test completion.','Analysis decides what to test (test conditions); design decides how to test (test cases); implementation builds testware and schedules; execution runs the tests; completion archives testware and captures lessons learned.','Testware examples: test plans, test cases, test data, test scripts, test results, defect reports, test reports. Traceability links the test basis, test cases and results.','Two typical roles: the test management role (planning, control, leading) and the testing role (analysis, design, implementation, execution).'],array['Plan, monitor and control, analyze, design, implement, execute, complete','Analysis = what, design = how']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=3),'Test basis','The information used as the basis for test analysis and design.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=3),'Testware','Work products produced during the test process, such as test cases and test data.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=3),'Traceability','A documented link between related items, such as requirements and test cases.',2);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=1 and position=3),'Test condition','A testable aspect of a component or system identified as a basis for testing.',3);
insert into summary_sections (chapter_id,position,title,points,memo) values (2,0,'Testing in the lifecycle',array['Whatever the lifecycle model, good practice applies: every development activity has a corresponding test activity, each test level has specific objectives, test analysis and design start during the matching development activity, and testers join reviews of work products early.','Shift left means testing earlier, for example through reviews, TDD, ATDD and BDD.','TDD writes tests before code. ATDD derives acceptance tests from acceptance criteria before implementation. BDD describes behavior in natural language such as Given/When/Then.','DevOps relies on continuous integration and delivery with automated regression testing. Retrospectives drive process improvement.'],array['Test early (shift left)','TDD: unit tests first','ATDD: acceptance tests first','BDD: Given, When, Then']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=0),'TDD','Test-driven development: write automated tests first, then code to pass them.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=0),'ATDD','Acceptance test-driven development: acceptance tests derived from acceptance criteria before implementation.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=0),'BDD','Behavior-driven development: expected behavior written in natural language, often Given/When/Then.',2);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=0),'Retrospective','A meeting at the end of an iteration or project to discuss what went well and what to improve.',3);
insert into summary_sections (chapter_id,position,title,points,memo) values (2,1,'Test levels',array['Component testing focuses on separately testable components. Component integration testing focuses on interfaces and interactions between components.','System testing focuses on the behavior and capabilities of the whole system, including end-to-end tasks. System integration testing focuses on interfaces with other systems and external services.','Acceptance testing validates the system and builds confidence it is ready for deployment. Forms include user acceptance testing (UAT), operational acceptance testing (OAT), contractual and regulatory acceptance testing, and alpha and beta testing.'],array['Component, component integration, system, system integration, acceptance','UAT, OAT, contractual/regulatory, alpha, beta']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=1),'UAT','User acceptance testing: validates fitness for use by intended users.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=1),'OAT','Operational acceptance testing: checks operational aspects such as backup and restore, installation, maintenance and security.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=1),'Alpha testing','Acceptance testing at the developer''s site by potential or existing customers or an independent team.',2);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=1),'Beta testing','Acceptance testing at the customers'' or operators'' own sites.',3);
insert into summary_sections (chapter_id,position,title,points,memo) values (2,2,'Test types and change-related testing',array['Functional testing evaluates what the system should do. Non-functional testing evaluates how well it does it, using quality characteristics such as performance efficiency, usability, reliability and security (ISO/IEC 25010).','Black-box testing is based on specifications; white-box testing is based on the internal structure and implementation.','Confirmation testing checks that a fix worked. Regression testing checks for unintended side effects of a change and is a strong candidate for automation.','Maintenance testing follows modification, migration or retirement of a system. Impact analysis identifies which areas are affected and how much testing is needed.'],array['Functional = what','Non-functional = how well','Confirmation = the fix','Regression = side effects','Maintenance triggers: modification, migration, retirement']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=2),'Confirmation testing','Re-testing to confirm that a defect has been fixed.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=2),'Regression testing','Testing to detect unintended adverse effects of a change.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=2 and position=2),'Impact analysis','Identifying the intended and potential consequences of a change to decide testing scope.',2);
insert into summary_sections (chapter_id,position,title,points,memo) values (3,0,'Static testing basics',array['Static testing evaluates work products (requirements, user stories, designs, code, test cases) without executing them. It includes reviews (manual) and static analysis (tool-based).','Static testing finds defects directly, while dynamic testing first reveals failures.','Benefits: early detection, lower fixing cost, and finding defects that dynamic testing cannot easily find, such as ambiguous requirements or unreachable code.','Static analysis tools can detect coding-standard violations, unreachable code and undefined variables.'],array['Static = no execution','Reviews and static analysis','Finds defects, not failures']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=0),'Static analysis','Tool-supported evaluation of code or other work products without executing them.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=0),'Review','Manual evaluation of a work product by one or more people.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (3,1,'Review process and roles',array['Review activities: planning, review initiation, individual review, communication and analysis, fixing and reporting.','Roles: manager (decides what is reviewed and provides resources), author, moderator or facilitator, scribe or recorder, reviewer, and review leader.','Review techniques: ad hoc, checklist-based, scenarios and dry runs, perspective-based reading and role-based reading.'],array['Planning, Initiation, Individual review, Communication, Fixing','Roles: manager, author, moderator, scribe, reviewer, review leader']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=1),'Moderator','Also called facilitator; ensures the review meeting runs effectively.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=1),'Scribe','Also called recorder; collates anomalies and records decisions and findings.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=1),'Perspective-based reading','Reviewers take different stakeholder viewpoints to find defects.',2);
insert into summary_sections (chapter_id,position,title,points,memo) values (3,2,'Review types and success factors',array['Informal review: no defined process, low cost. Walkthrough: led by the author, used for learning, consensus and finding defects.','Technical review: performed by technically qualified reviewers, led by a moderator, aims at consensus and finding defects.','Inspection: the most formal type, with a defined process, roles, metrics, checklists and entry and exit criteria.','Success factors: clear objectives and measurable exit criteria, the right review type, small chunks, enough time, management support and a positive culture. Evaluating participants must never be an objective.'],array['Formality: informal < walkthrough < technical review < inspection']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=2),'Inspection','The most formal review type, following a defined process with roles and metrics.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=3 and position=2),'Walkthrough','A review led by the author to share knowledge and gather feedback.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (4,0,'Choosing test techniques',array['Test techniques help analyze the test basis and design test cases. Categories: black-box (specification-based), white-box (structure-based) and experience-based.','Test analysis identifies test conditions; test design turns them into test cases.','Black-box techniques: equivalence partitioning, boundary value analysis, decision table testing, state transition testing.','White-box techniques: statement testing and branch testing.','Experience-based techniques: error guessing, exploratory testing, checklist-based testing.'],array['Black-box: the specification','White-box: the code structure','Experience-based: skill and intuition']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=0),'Black-box testing','Testing based on specifications, without using the internal structure.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=0),'White-box testing','Testing based on the internal structure of the test object.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (4,1,'Black-box techniques',array['Equivalence partitioning: divide data into partitions expected to be processed alike, valid and invalid. Coverage = partitions exercised / total partitions; one value represents its partition.','Boundary value analysis: extends equivalence partitioning for ordered partitions. 2-value BVA tests a boundary and its closest neighbor in the adjacent partition; 3-value BVA also tests the other neighbor.','Decision table testing: combinations of conditions and the resulting actions. A full table has 2^n columns for n binary conditions; rules can be collapsed where a condition is irrelevant. Coverage = feasible columns exercised / total feasible columns.','State transition testing: states, events, guard conditions, transitions and actions. Coverage criteria: all states, valid transitions (0-switch) and all transitions.'],array['EP: one value per partition','2-value BVA: boundary plus neighbor outside','3-value BVA: before, on, after','Decision table: 2^n columns','State: all states, valid transitions, all transitions']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=1),'Equivalence partition','A group of values that the test object should treat the same way.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=1),'Boundary value','The minimum or maximum value of an ordered equivalence partition.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=1),'Decision table','A table of condition combinations and the actions each combination triggers.',2);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=1),'Guard condition','A condition that must be true for a state transition to occur.',3);
insert into summary_sections (chapter_id,position,title,points,memo) values (4,2,'White-box techniques',array['Statement testing exercises executable statements. Coverage = statements exercised / total executable statements.','Branch testing exercises branches, the outcomes of decisions such as the true and false outcomes of an if. Coverage = branches exercised / total branches.','100% branch coverage guarantees 100% statement coverage, but not the reverse.','White-box testing considers the whole implementation and can find defects even when requirements are missing or incomplete, but it cannot detect missing functionality by itself.'],array['Branch coverage implies statement coverage','Statement coverage does not imply branch coverage']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=2),'Statement coverage','Percentage of executable statements exercised by tests.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=2),'Branch coverage','Percentage of branches (decision outcomes) exercised by tests.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (4,3,'Experience-based and collaboration-based',array['Error guessing anticipates defects from experience, defect history and knowledge of common mistakes.','Exploratory testing combines learning, test design and execution at the same time, often time-boxed and guided by a test charter (session-based).','Checklist-based testing designs tests from a checklist of conditions; checklists should be maintained.','Collaborative user story writing uses the three Cs (Card, Conversation, Confirmation) and the INVEST qualities. Acceptance criteria can be rule-oriented or scenario-oriented (Given/When/Then).','ATDD derives acceptance tests from acceptance criteria before implementation.'],array['Three Cs: Card, Conversation, Confirmation','INVEST: Independent, Negotiable, Valuable, Estimable, Small, Testable','Exploratory: charter plus time box']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=3),'Test charter','A short statement of the goals of an exploratory testing session.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=3),'Acceptance criteria','Conditions a user story must satisfy to be accepted.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=4 and position=3),'INVEST','Quality attributes of a good user story.',2);
insert into summary_sections (chapter_id,position,title,points,memo) values (5,0,'Test planning and estimation',array['A test plan describes objectives, scope, approach, resources, schedule and risks, and evolves during the project.','Entry criteria (Definition of Ready) are the preconditions to start testing. Exit criteria (Definition of Done) define when testing can stop, such as planned tests executed, coverage reached and defect thresholds met.','Estimation techniques: ratio-based, extrapolation, Wideband Delphi and three-point estimation, where E = (a + 4m + b) / 6.','Prioritization approaches: risk-based, coverage-based and requirements-based.','Test pyramid: many fast, isolated low-level tests and few slow, high-level tests. Testing quadrants group tests by technology-facing or business-facing and by supporting the team or critiquing the product.'],array['Entry = Definition of Ready, exit = Definition of Done','E = (a + 4m + b) / 6','Pyramid: many unit tests, few UI tests']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=0),'Three-point estimation','Expert technique using optimistic (a), most likely (m) and pessimistic (b) estimates: E = (a + 4m + b) / 6.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=0),'Wideband Delphi','Iterative, expert-based estimation: experts estimate alone, discuss deviations, and re-estimate until consensus.',1);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=0),'Definition of Done','Agreed criteria for considering work complete; exit criteria in agile teams.',2);
insert into summary_sections (chapter_id,position,title,points,memo) values (5,1,'Risk-based testing',array['Risk level is determined by the likelihood of an event and its impact.','Project risks concern managing and controlling the project (organizational, people, technical and supplier issues). Product risks concern the quality of the test object, such as wrong calculations, poor performance or poor usability.','Product risk analysis (identification and assessment) drives test priority and depth. Risk control includes mitigation and monitoring.'],array['Risk level = likelihood and impact','Project risk: how we deliver','Product risk: what we deliver']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=1),'Product risk','A risk to the quality of the product, such as incorrect functions or poor performance.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=1),'Project risk','A risk to the management and control of the project, such as staff loss or late delivery.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (5,2,'Monitoring, control, reporting and defects',array['Test metrics cover project progress, test progress, product quality, defects, risks, coverage and cost.','A test progress report is produced during testing; a test summary report at completion. Communicate the right information to the right stakeholders.','Configuration management keeps testware and test objects traceable and reproducible.','A defect report typically contains an identifier, title, date, author, test object and environment, description of the failure with steps to reproduce, expected and actual results, severity, priority and status.'],array['Progress report during, summary report at the end','Defect report: expected vs actual, severity, priority']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=2),'Configuration management','Controls versions of testware and test objects for traceability and reproducibility.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=5 and position=2),'Severity and priority','Severity is the impact of a defect; priority is the order in which it should be fixed.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (6,0,'Tool support for testing',array['Tools support test activities across the process but do not replace human judgment.','Categories: test management, static testing, test design and implementation, test execution and coverage, non-functional testing (such as performance), DevOps and collaboration tools, and others such as spreadsheets.'],array['Tools support testers, they do not replace them']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=6 and position=0),'Test execution tool','A tool that runs tests automatically and compares actual with expected results.',0);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=6 and position=0),'Coverage tool','A tool that measures how much of the code or other structure the tests exercised.',1);
insert into summary_sections (chapter_id,position,title,points,memo) values (6,1,'Benefits and risks of test automation',array['Benefits: time savings and less repetitive manual work, greater consistency and repeatability, more objective assessment, easier access to test information, and fewer human errors in repetitive tasks.','Risks: unrealistic expectations, underestimating the time, cost and effort to build and maintain automation, using the tool for the wrong purpose, over-reliance on the tool, vendor or open-source concerns, and incompatibility with the development platform.'],array['Benefits: time, consistency, objectivity, less repetition','Risks: expectations, effort, maintenance, over-reliance']);
insert into summary_terms (section_id,term,definition,position) values ((select id from summary_sections where chapter_id=6 and position=1),'Test automation','Using tools to perform or support test activities.',0);
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (4,'K2','Our suite reached 100% statement coverage, so every decision outcome (true and false) has been tested.',array['Statement coverage ignores which tests were executed','100% statement coverage does not guarantee every branch outcome was exercised, for example an if without an else','The claim is only wrong for compiled languages','Branch coverage is a weaker criterion than statement coverage'],1,'Coverage-type swap','100% branch coverage guarantees 100% statement coverage, but not the other way around.');
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (1,'K2','We ran 500 tests and found no defects, so the software is defect-free and can ship.',array['The tests were probably badly written','Testing can show the presence of defects but cannot prove their absence','500 tests is always too few for a release','Defect-free software never needs testing'],1,'Absolute-claim trap','Testing reduces the probability of undiscovered defects but is not proof of correctness (testing principle 1).');
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (2,'K2','The login defect was fixed and the failed test now passes, so we know no other function was affected.',array['Confirmation testing only checks the fix; regression testing is needed to look for side effects','The failed test should have been deleted','Passing tests are proof that nothing else changed','Only acceptance testing can find side effects'],0,'Test-type mix-up','Confirmation testing verifies the fix itself. Regression testing checks for unintended effects elsewhere.');
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (4,'K3','The valid range is 18 to 65, so boundary value analysis needs only the values 18 and 65.',array['Boundary value analysis never uses valid values','2-value BVA also needs the closest value in each adjacent partition, here 17 and 66','Only 19 and 64 are boundaries','Boundary values cannot be applied to ages'],1,'Half-answer trap','2-value BVA tests each boundary and its nearest neighbor in the adjacent partition: 17, 18, 65, 66.');
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (1,'K2','Testers should fix the defects they find, because debugging is simply part of testing.',array['Testers are not allowed to read code','Debugging, finding and removing the cause of a failure, is a development activity; testing reveals the failures','Debugging only happens after release','Testing and debugging are the same thing'],1,'Terminology swap','Testing triggers failures or finds defects. Debugging locates and removes their causes, and confirmation testing then checks the fix.');
insert into reasoning_cards (chapter_id,k_level,claim,flaw_options,flaw_index,trap,correction) values (5,'K2','A risk''s level is decided by its impact alone, so we always test the highest-impact area first.',array['Impact is irrelevant to risk','Risk level combines likelihood and impact, and the word ''alone'' makes the claim wrong','Likelihood alone decides risk level','Risk level cannot be estimated'],1,'Single-factor trap','Risk level is determined by likelihood and impact together; priorities come from that combination.');
